using Idasletten.Features.Tournaments;
using Idasletten.Features.Tournaments.Commands;
using Idasletten.Shared;
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace Idasletten.Features.Matches;

/// <summary>
/// Resolves team inputs (lists of player initials) to TournamentTeams.
/// Unknown initials auto-create the User and TournamentPlayer. An existing team
/// with exactly the same players is reused; otherwise a new team is created with
/// an autogenerated name/number ("Team 1", "Team 2", ...).
/// </summary>
public static class TeamResolver
{
    public static async Task<List<TournamentTeam>> ResolveTeams(
        AppDbContext db,
        IMediator mediator,
        Tournament tournament,
        IReadOnlyList<IReadOnlyList<string>> teamInitials,
        CancellationToken ct)
    {
        var teams = new List<TournamentTeam>();
        foreach (var initialsList in teamInitials)
        {
            var players = new List<TournamentPlayer>();
            foreach (var initials in initialsList.Select(i => i.Trim()).Where(i => i.Length > 0))
                players.Add(await mediator.Send(new AddPlayerToTournamentCommand(tournament.Id, initials), ct));

            if (players.Count == 0)
                throw new InvalidOperationException("Each team needs at least one player.");

            teams.Add(await FindOrCreateTeam(db, tournament, players, ct));
        }

        if (teams.Count < 2)
            throw new InvalidOperationException("A match needs at least two teams.");
        return teams;
    }

    public static async Task<TournamentTeam> FindOrCreateTeam(
        AppDbContext db,
        Tournament tournament,
        List<TournamentPlayer> players,
        CancellationToken ct)
    {
        var playerIds = players.Select(p => p.Id).OrderBy(id => id).ToList();

        var candidates = await db.TournamentTeams
            .Include(t => t.Players)
            .Where(t => t.TournamentId == tournament.Id)
            .ToListAsync(ct);

        var existing = candidates.FirstOrDefault(t =>
            t.Players.Select(p => p.Id).OrderBy(id => id).SequenceEqual(playerIds));
        if (existing is not null)
            return existing;

        var number = candidates.Count == 0 ? 1 : candidates.Max(t => t.Number) + 1;
        var team = new TournamentTeam
        {
            TournamentId = tournament.Id,
            Number = number,
            Name = $"Team {number}",
            Players = players
        };
        db.TournamentTeams.Add(team);
        await db.SaveChangesAsync(ct);
        return team;
    }
}
